'use strict';
const PLANNING_UI6={financeView,boardView,render,bind,report};
function planPanel6(){const p=state.planning6.current,a=p?planAssessment6(p):null;return `<section class="card" style="margin-bottom:24px"><div class="card-head"><h2>Čtvrtletní plán firmy</h2><button class="primary" id="companyPlanEdit6">${p?'Upravit plán':'Sestavit plán'}</button></div><p class="sub">${p?'T'+p.start+'–'+p.end+' · '+a.done+' / 13 skutečných týdnů · '+p.revisions.length+' revizí.':'Urči cíle na příštích 13 odehraných týdnů a rozvojové rozpočty.'} Rozpočet nepřidává peníze. Sjednané mzdy, nájmy a faktury zůstávají splatné.</p>${p?`<div class="table-scroll"><table class="data"><thead><tr><th>Rozvojové platby</th><th>Limit</th><th>Skutečně zaplaceno</th><th>Zbývá / přesah</th></tr></thead><tbody>${a.budgets.map(b=>`<tr><td>${PLAN_CATEGORIES6[b.category]}</td><td>${money(b.target)}</td><td>${money(b.actual)}</td><td class="${b.variance>0?'bad':'good'}">${money(b.target-b.actual)}</td></tr>`).join('')}</tbody></table></div><p class="sub">${p.enforce?'Nové kroky jsou omezené zbývajícím rozpočtem.':'Limity slouží k porovnání; nové kroky nejsou blokované.'} Průběžný výsledek ${money(a.profit)}, tržby ${money(a.revenue)}. Sjednaný provoz za období ${money(a.operating)} je oddělený od rozvojových plateb.</p><button class="soft" data-plan-report6="current">Otevřít cíle a odchylky</button>`:''}${state.planning6.archive.length?`<div class="actions">${state.planning6.archive.slice().reverse().map(p=>`<button class="soft" data-plan-report6="${p.start}">Uzavření T${p.start}–${p.end}</button>`).join('')}</div>`:''}</section>`;}
financeView=function(){return planPanel6()+`<section class="card" style="margin-bottom:24px"><div class="card-head"><h2>Proč se změnil výsledek</h2><button class="soft" data-profit-causes6="company">Otevřít rozklad zisku</button></div><p class="sub">Porovnej skutečné účetní výsledky firmy i každé kavárny. Náklady, spotřeba a odpad vycházejí z uzavřených týdnů.</p><div class="actions">${state.stores.map(s=>`<button class="soft" data-profit-causes6="${s.id}">${esc(loc(s.id).name)}</button>`).join('')}</div></section>`+PLANNING_UI6.financeView();};
boardView=function(){return planPanel6()+PLANNING_UI6.boardView();};
function planEditDialog6(){const p=state.planning6.current,d=p?{goals:p.goals,budgets:p.budgets,enforce:p.enforce}:planDefaultData6();show(`<h2>${p?'Revize':'Nový'} čtvrtletní plán</h2><p class="sub">Období T${p?.start||state.week}–${p?.end||state.week+12}. Cíle tržeb a výsledku jsou součty za 13 týdnů. Revize nesmaže dosavadní platby.</p><div class="fields">${Object.entries(PLAN_CATEGORIES6).map(([k,label])=>field(label,input('planBudget-'+k,d.budgets[k],0,1e9,1000))).join('')}${field('Výsledek celého období',input('planGoal-profit',d.goals.profit,-1e9,1e9,1000))}${field('Tržby celého období',input('planGoal-revenue',d.goals.revenue,0,1e10,1000))}${field('Počet kaváren na konci',input('planGoal-stores',d.goals.stores,0,LOCATIONS.length))}${field('Kvalita / 100',input('planGoal-quality',d.goals.quality,0,100))}${field('Rezerva · týdny závazků',input('planGoal-reserve',d.goals.reserve,0,13))}</div><label><input id="planEnforce6" type="checkbox" ${d.enforce?'checked':''}> Hlídání nových rozvojových výdajů</label><p class="sub">Expanze zahrnuje nové provozy, budovy, vybavení a akademii. Výroba nové zásoby, balení, dopravu a vývoj produktů. Lidé nábor a výcvik. Marketing identity a kampaně. Běžný provoz, servis a sjednané faktury se platí dál.</p><button class="primary" id="planSave6">Prověřit plán</button>`);el('planSave6').onclick=()=>{try{const data={budgets:Object.fromEntries(Object.keys(PLAN_CATEGORIES6).map(k=>[k,Number(el('planBudget-'+k).value)])),goals:Object.fromEntries(Object.keys(d.goals).map(k=>[k,Number(el('planGoal-'+k).value)])),enforce:el('planEnforce6').checked},q=planQuote6(data);confirmAction('Uložit čtvrtletní plán?', 'T'+q.start+'–'+q.end+' · rozvojové limity '+money(Object.values(data.budgets).reduce((n,x)=>n+x,0))+'. Platby zůstávají '+money(Object.values(q.spent).reduce((n,x)=>n+x,0))+'. Hotovost se nezmění.',()=>setCompanyPlan6(data,q),'Uložit plán');}catch(e){toast(e.message);}};}
function planReportDialog6(key){const p=key==='current'?state.planning6.current:state.planning6.archive.find(p=>p.start===Number(key));if(!p)return;const a=planAssessment6(p);show(`<h2>Plán firmy · T${p.start}–${p.end}</h2><p class="sub">${a.done} uzavřených týdnů. ${esc(a.explanation)}</p><div class="table-scroll"><table class="data"><thead><tr><th>Cíl</th><th>Plán</th><th>Skutečnost</th><th>Odchylka</th></tr></thead><tbody>${a.rows.map((r,i)=>`<tr><td>${r.label}</td><td>${i<2?money(r.target):number(r.target,1)}</td><td>${i<2?money(r.actual):number(r.actual,1)}</td><td class="${r.variance<0?'bad':'good'}">${i<2?money(r.variance):number(r.variance,1)}</td></tr>`).join('')}</tbody></table></div><h3>Vysvětlení boardu</h3>${a.notes.map(t=>`<p class="sub">${esc(t)}</p>`).join('')}<h3>Rozvojové rozpočty</h3>${rows(a.budgets.map(b=>[PLAN_CATEGORIES6[b.category],money(b.actual)+' / '+money(b.target)+(b.variance>0?' · překročení '+money(b.variance):'')]))}<p class="sub">Provozní náklady včetně daně a odpisů ${money(a.operating)}. Výroba sleduje zaplacené zásoby; zisk zatěžuje až jejich spotřeba nebo odpis.</p><button class="soft" id="planCauses6">Rozklad změny výsledku</button><h3>Revize cílů a limitů</h3>${p.revisions.map((r,i)=>`<p class="sub">Revize ${i+1} · T${r.week} · cíl zisku ${money(r.goals.profit)} · rozvojové limity ${money(Object.values(r.budgets).reduce((n,x)=>n+x,0))}</p>`).join('')}<h3>Poslední skutečné rozvojové platby</h3>${p.events.slice(-20).reverse().map(e=>`<p class="sub">T${e.week} · ${PLAN_CATEGORIES6[e.category]} · ${money(e.amount)} · ${esc(e.label)}${e.mandatory?' · dříve sjednaný závazek':''}</p>`).join('')||'<p class="sub">Žádné rozvojové platby.</p>'}`);el('planCauses6').onclick=()=>profitCausesDialog6('company',1);}
function profitCausesDialog6(id='company',weeks=1){const r=profitCauses6(id,weeks),e=r.current?.evidence||{};show(`<h2>Proč se změnil zisk · ${esc(r.current?.name||(id==='company'?'Celá firma':loc(id).name))}</h2><div class="actions">${[1,4,13].map(n=>`<button class="${n===weeks?'primary':'soft'}" data-cause-period6="${n}">${n} ${n===1?'týden':'týdnů'}</button>`).join('')}</div>${!r.current?'<p class="empty">Nejprve odehraj skutečný týden. Starší uložené hry začnou sbírat podrobnou historii až od tohoto vydání.</p>':`<p class="sub">${r.previous?'Průměr T'+r.currentStart+'–'+r.to+' oproti T'+r.from+'–'+r.previousEnd: 'T'+r.currentStart+'–'+r.to+' · chybí celé předchozí období; změnu zatím nelze spočítat.'}</p>${rows([['Skutečný výsledek / týden',money(r.current.profit)],...(r.previous?[['Předchozí výsledek / týden',money(r.previous.profit)],['Změna výsledku',money(r.delta)]]:[])])}${r.previous?`<table class="data"><thead><tr><th>Účetní příspěvek ke změně</th><th>Dopad na zisk</th></tr></thead><tbody>${r.rows.map(x=>`<tr><td>${esc(x.label)}</td><td class="${x.effect>=0?'good':'bad'}">${money(x.effect)}</td></tr>`).join('')}</tbody></table><p class="sub">Součet ${money(r.rows.reduce((n,x)=>n+x.effect,0))} odpovídá změně zisku. Cena a skladba nabídky zahrnují i změnu nákupního košíku hostů.</p>`:''}<h3>Co se skutečně dělo v provozu</h3>${rows([['Obsloužení hosté / týden',number(r.current.served,1)],['Poptávka hostů',number(e.demand||0,1)],['Hosté ztracení nedostatkem kávy',number(e.stockLost||0,1)],['Hosté ztracení kapacitou',number(e.capacityLost||0,1)],['Chybějící směny / pracovníci',number(e.staffGap||0,1)],...(id!=='company'?[['Čekání · minuty',number(e.wait||0,1)],['Kvalita',number(e.quality||0,1)],['Podíl týdnů ve zkušebním provozu',number((e.trial||0)*100,0)+' %']]:[['Daň jako část provozních nákladů',money(e.tax||0)],['Účetní odpisy jako část nákladů',money(e.depreciation||0)]]),['Hodnota odepsaného jídla',money(e.foodWaste||0)]])}<p class="sub">Účetní rozklad vysvětluje, které položky změnily výsledek. Provozní údaje ukazují souvislosti; samy neprokazují, že jediná změna způsobila celý rozdíl.</p>`}`);on('[data-cause-period6]',b=>profitCausesDialog6(id,Number(b.dataset.causePeriod6)));}
bind=function(){PLANNING_UI6.bind();if(el('companyPlanEdit6'))el('companyPlanEdit6').onclick=planEditDialog6;on('[data-plan-report6]',b=>planReportDialog6(b.dataset.planReport6));on('[data-profit-causes6]',b=>profitCausesDialog6(b.dataset.profitCauses6));};
report=function(id,...a){PLANNING_UI6.report(id,...a);const b=document.createElement('button');b.className='soft';b.textContent='Proč se změnil zisk';b.onclick=()=>profitCausesDialog6(id);el('modalContent').append(b);};
render=function(){PLANNING_UI6.render();const metric=el('metrics')?.children[1];if(metric){const button=document.createElement('button');button.className='quiet';button.textContent='Proč se změnil výsledek ↗';button.onclick=()=>profitCausesDialog6('company');metric.append(button);}};render();
